/**
 * Identity of the vendored pricing module, returned with every quote so the
 * POS can check at runtime that it runs the same module as the server.
 *
 * The constants are generated by scripts/vendor-ordr-core.mjs into
 * ordrCoreInfo.generated.ts (no JSON-import bundling needed) and verified
 * against ordr-core/VENDORED.json by scripts/check-ordr-core.mjs.
 *
 * pricingModuleHash = sha256 (hex) of "<sha256>  <path>\n" for each vendored
 * file, path ascending — what `sha256sum` prints in ordr-pos src/core.
 */
export { PRICING_MODULE_HASH, SOURCE_COMMIT } from './ordrCoreInfo.generated.ts';
